+            salt_hex[salt_hex_sz - 1] = '\0';
+            strncpy(hash_hex, h, hash_hex_sz - 1);
+            hash_hex[hash_hex_sz - 1] = '\0';
+            found = 1;
+            break;
+        }
+    }
+    fclose(f);
+    return found ? 0 : 1; /* 0=ok/found, 1=not found, -1=io error */
+}
+
+static int sha256_salt_password(const unsigned char* salt, size_t salt_len,
+                                const char* password, unsigned char out[SHA256_LEN]) {
+    SHA256_CTX ctx;
+    if (SHA256_Init(&amp;ctx) != 1) return -1;
+    if (SHA256_Update(&amp;ctx, salt, salt_len) != 1) return -1;
+    if (SHA256_Update(&amp;ctx, (const unsigned char*)password, strlen(password)) != 1) return -1;
+    if (SHA256_Final(out, &amp;ctx) != 1) return -1;
+    return 0;
+}
+
+static int random_bytes(unsigned char* out, size_t len) {
+    int fd = open("/dev/urandom", O_RDONLY);
+    if (fd &lt; 0) return -1;
+    size_t got = 0;
+    while (got &lt; len) {
+        ssize_t r = read(fd, out + got, len - got);
+        if (r &lt; 0) {
+            if (errno == EINTR) continue;
+            close(fd);
+            return -1;
+        }
+        if (r == 0) break;
+        got += (size_t)r;
+    }
+    close(fd);
+    return got == len ? 0 : -1;
+}
+
+static void respond_unauthorized(void) {
+    print_http_header("401 Unauthorized",
+                      "Set-Cookie: session=; Max-Age=0; Path=/; HttpOnly; SameSite=Lax\r\n");
+    printf("&lt;!doctype html&gt;&lt;html&gt;&lt;body&gt;&lt;h1&gt;Unauthorized&lt;/h1&gt;&lt;p&gt;Invalid username or password.&lt;/p&gt;&lt;/body&gt;&lt;/html&gt;\n");
+}
+
+static void respond_server_error(const char* msg) {
+    print_http_header("500 Internal Server Error", NULL);
+    printf("&lt;!doctype html&gt;&lt;html&gt;&lt;body&gt;&lt;h1&gt;Server Error&lt;/h1&gt;&lt;pre&gt;%s&lt;/pre&gt;&lt;/body&gt;&lt;/html&gt;\n",
+           msg ? msg : "Unknown error");
+}
+
+int main(void) {
+    char form[MAX_FORM_SIZE] = {0};
+    const char* method = getenv("REQUEST_METHOD");
+    size_t form_len = 0;
+
+    if (method &amp;&amp; strcmp(method, "POST") == 0) {
+        if (read_post_body(form, sizeof(form), &amp;form_len) != 0) {
+            respond_server_error("Failed to read POST body");
+            return 0;
+        }
+    } else {
+        const char* qs = getenv("QUERY_STRING");
+        if (qs) {
+            strncpy(form, qs, sizeof(form) - 1);
+            form[sizeof(form) - 1] = '\0';
+            form_len = strlen(form);
+        }
+    }
+
+    url_decode_inplace(form);
+
+    char username[MAX_FIELD_SIZE] = {0};
+    char password[MAX_FIELD_SIZE] = {0};
+
+    if (!parse_kv_param(form, "username", username, sizeof(username)) ||
+        !parse_kv_param(form, "password", password, sizeof(password))) {
+        print_http_header("400 Bad Request", NULL);
+        printf("&lt;!doctype html&gt;&lt;html&gt;&lt;body&gt;&lt;h1&gt;Bad Request&lt;/h1&gt;&lt;p&gt;Missing username or password.&lt;/p&gt;&lt;/body&gt;&lt;/html&gt;\n");
+        return 0;
+    }
+
+    const char* db_path = getenv("AUTH_USER_DB");
+    if (!db_path || !*db_path) db_path = DEFAULT_DB_PATH;
+
+    char salt_hex[129] = {0};  /* up to 64 bytes salt -&gt; 128 hex chars */
+    char hash_hex[129] = {0};  /* 32 bytes digest -&gt; 64 hex chars (buffer larger for safety) */
+    int gr = get_user_record(username, salt_hex, sizeof(salt_hex), hash_hex, sizeof(hash_hex), db_path);
+    if (gr == -1) {
+        respond_server_error("User database not accessible");
+        return 0;
+    }
+    if (gr == 1) {
+        respond_unauthorized();
+        return 0;
+    }
+
+    unsigned char salt_bin[64] = {0};
+    int salt_len = hex_decode(salt_hex, salt_bin, sizeof(salt_bin));
+    if (salt_len &lt;= 0) {
+        respond_server_error("Invalid salt encoding in DB");
+        return 0;
+    }
+
+    unsigned char stored_hash[SHA256_LEN] = {0};
+    int shlen = hex_decode(hash_hex, stored_hash, sizeof(stored_hash));
+    if (shlen != SHA256_LEN) {
+        respond_server_error("Invalid hash encoding in DB");
+        return 0;
+    }
+
+    unsigned char calc_hash[SHA256_LEN] = {0};
+    if (sha256_salt_password(salt_bin, (size_t)salt_len, password, calc_hash) != 0) {
+        respond_server_error("Hashing failed");
+        return 0;
+    }
+
+    if (ct_memcmp(calc_hash, stored_hash, SHA256_LEN) != 0) {
+        respond_unauthorized();
+        return 0;
+    }
+
+    unsigned char token_bin[32];
+    if (random_bytes(token_bin, sizeof(token_bin)) != 0) {
+        respond_server_error("Random token generation failed");
+        return 0;
+    }
+    char token_hex[65];
+    hex_encode(token_bin, sizeof(token_bin), token_hex);
+
+    char cookie_hdr[256 + 64];
+    snprintf(cookie_hdr, sizeof(cookie_hdr),
+             "Set-Cookie: session=%s; HttpOnly; SameSite=Lax; Path=/\r\n", token_hex);
+
+    print_http_header("200 OK", cookie_hdr);
+    printf("&lt;!doctype html&gt;&lt;html&gt;&lt;body&gt;&lt;h1&gt;Login successful&lt;/h1&gt;&lt;p&gt;Welcome, %s!&lt;/p&gt;&lt;/body&gt;&lt;/html&gt;\n",
+           username);
+
+    return 0;
+}
+
+/*
+Helper: How to create a user entry
+----------------------------------
+1) Generate a random salt (16 bytes recommended), hex-encode it.
+2) Compute hash = SHA256( salt || password ), hex-encode it.
+3) Add line: username:salt_hex:hash_hex
+
+Example (bash + OpenSSL):
+    USER=jdoe
+    PASS='S3cur3P@ss'
+    SALT_HEX=$(openssl rand -hex 16)
+    HASH_HEX=$(printf %s "$PASS" | xxd -p -r | (printf %s "$SALT_HEX" | xxd -p -r; cat) | openssl dgst -sha256 -r | awk '{print $1}')
+    echo "$USER:$SALT_HEX:$HASH_HEX" &gt;&gt; /workspace/users.db
+
+Form example (POST to CGI):
+    &lt;form method="POST" action="/cgi-bin/auth.cgi"&gt;
+      &lt;input name="username" /&gt;
+      &lt;input name="password" type="password" /&gt;
+      &lt;button type="submit"&gt;Login&lt;/button&gt;
+    &lt;/form&gt;
+*/

