/*
Simple CGI-based user authentication in C.

- Expects application/x-www-form-urlencoded fields: username and password
- Verifies credentials against a flat file user database (default: /workspace/users.db)
- Passwords are verified using SHA-256 over: hash = SHA256( salt || password )
- User DB format (one user per line):
    username:salt_hex:hash_hex
  where:
    - salt_hex is hex-encoded random salt (recommended 16-32 bytes, i.e., 32-64 hex chars)
    - hash_hex is hex-encoded 32-byte SHA-256 digest (64 hex chars)

Environment/CGI:
- REQUEST_METHOD: GET or POST
- QUERY_STRING (for GET)
- CONTENT_LENGTH and stdin (for POST)

Build:
  gcc -O2 -o auth.cgi /workspace/web_app.c -lcrypto

Optional environment variable:
- AUTH_USER_DB: path to user DB file (overrides default)

This is a minimal example and should be placed behind HTTPS. Add CSRF protection when embedding in real forms.
*/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <openssl/sha.h>

#define MAX_FORM_SIZE     4096
#define MAX_FIELD_SIZE     256
#define MAX_LINE_SIZE     2048
#define SHA256_LEN          32
#define DEFAULT_DB_PATH "/workspace/users.db"

static void print_http_header(const char* status, const char* extra_headers) {
    if (status && *status) {
        printf("Status: %s\r\n", status);
    }
    printf("Content-Type: text/html; charset=utf-8\r\n");
    if (extra_headers && *extra_headers) {
        printf("%s", extra_headers);
        if (extra_headers[strlen(extra_headers)-1] != '\n') printf("\r\n");
    }
    printf("\r\n");
}

static int hex_val(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static int hex_decode(const char* hex, unsigned char* out, size_t max_out) {
    size_t len = strlen(hex);
    if (len % 2 != 0) return -1;
    size_t out_len = len / 2;
    if (out_len > max_out) return -1;
    for (size_t i = 0; i < out_len; i++) {
        int hi = hex_val(hex[2*i]);
        int lo = hex_val(hex[2*i + 1]);
        if (hi < 0 || lo < 0) return -1;
        out[i] = (unsigned char)((hi << 4) | lo);
    }
    return (int)out_len;
}

static void hex_encode(const unsigned char* in, size_t len, char* out /* size 2*len+1 */) {
    static const char* H = "0123456789abcdef";
    for (size_t i = 0; i < len; i++) {
        out[2*i]     = H[(in[i] >> 4) & 0xF];
        out[2*i + 1] = H[in[i] & 0xF];
    }
    out[2*len] = '\0';
}

static int ct_memcmp(const unsigned char* a, const unsigned char* b, size_t n) {
    unsigned char diff = 0;
    for (size_t i = 0; i < n; i++) diff |= (unsigned char)(a[i] ^ b[i]);
    return diff; /* 0 if equal */
}

static void url_decode_inplace(char* s) {
    char* src = s;
    char* dst = s;
    while (*src) {
        if (*src == '+') {
            *dst++ = ' ';
            src++;
        } else if (*src == '%' && isxdigit((unsigned char)src[1]) && isxdigit((unsigned char)src[2])) {
            int hi = hex_val(src[1]);
            int lo = hex_val(src[2]);
            *dst++ = (char)((hi << 4) | lo);
            src += 3;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
}

static int parse_kv_param(const char* query, const char* key, char* out, size_t out_sz) {
    size_t key_len = strlen(key);
    const char* p = query;
    while (p && *p) {
        const char* amp = strchr(p, '&');
        size_t seg_len = amp ? (size_t)(amp - p) : strlen(p);
        const char* eq = memchr(p, '=', seg_len);
        if (eq) {
            size_t klen = (size_t)(eq - p);
            if (klen == key_len && strncmp(p, key, key_len) == 0) {
                size_t vlen = seg_len - klen - 1;
